import React from "react";
import { useParams } from "react-router-dom";
import { useProductView } from "./useProductView";
import {
  Row,
  Col,
  Card,
  Label,
  Input,
  Button,
  CardImg,
  CardText,
  CardBody,
  CardTitle,
  FormGroup,
  CardSubtitle,
} from "reactstrap";

const ProductView = () => {
  const { id: productId } = useParams(); // Extract productId from URL
  const {
    product,
    getImage,
    selectedColor,
    selectedSize,
    selectedQuantity,
    setSelectedColor,
    setSelectedSize,
    handleQuantityChange,
  } = useProductView(productId);

  if (!product) return <div>Loading...</div>;

  const quantity = Array.from(
    Array(Number(product.quantity || 0)).keys()
  );

  return (
    <Card className="product-details">
      <Row>
        <Col sm="12" md="4">
          <CardImg
            left="true"
            width="100%"
            src={`http://localhost:1337${getImage(selectedColor)}`}
            alt="Product"
          />
        </Col>
        <Col sm="12" md="8">
          <CardBody>
            <CardTitle>{product.name}</CardTitle>
            <CardText>{product.description}</CardText>
            <CardSubtitle>
              <strong>Price: £{product.price}</strong>
            </CardSubtitle>
            <CardSubtitle>{product.quantity} items Left</CardSubtitle>

            {/* Sizes */}
            <div>
              <CardSubtitle>Sizes:</CardSubtitle>
              <div className="sizes">
                {product.sizes.map((size) => (
                  <span
                    key={size.name}
                    className={`${selectedSize === size.name ? "active" : ""}`}
                    onClick={() => setSelectedSize(size.name)}
                  >
                    {size.name}
                  </span>
                ))}
              </div>
            </div>

            {/* Colors */}
            <div>
              <CardSubtitle>Selected color: {selectedColor}</CardSubtitle>
              <div className="colors">
                {product.colors.map((color) => (
                  <span
                    key={color.name}
                    className={`${selectedColor === color.name ? "active" : ""}`}
                    onClick={() => setSelectedColor(color.name)}
                  >
                    <img
                      src={`http://localhost:1337${getImage(color.name)}`}
                      alt={color.name}
                    />
                  </span>
                ))}
              </div>
              <FormGroup className="quantity">
                <Label for="quantitySelect">Select Quantity</Label>
                <Input
                  value={selectedQuantity}
                  type="select"
                  name="quantity"
                  id="quantitySelect"
                  onChange={handleQuantityChange}
                >
                  {quantity.map((num) => (
                    <option key={num}>{num + 1}</option>
                  ))}
                </Input>
              </FormGroup>
            </div>

            <Button color="primary">Add to Cart</Button>
          </CardBody>
        </Col>
      </Row>
    </Card>
  );
};

export default ProductView;
